const sources = [
  {
    provider: 'BankBazaar',
    url: 'https://www.bankbazaar.com/personal-loan.html',
  },
  {
    provider: 'Paisabazaar',
    url: 'https://www.paisabazaar.com/personal-loan/',
  },
  {
    provider: 'HDFC Bank',
    url: 'https://www.hdfcbank.com/personal/borrow/popular-loans/personal-loan',
  },
];

return sources.map(source => ({
  json: source,
}));

return $input.all().map(item => {
  const html = item.json.data ?? '';

  const text = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();

  return {
    json: {
      provider: item.json.provider,
      url: item.json.url,
      text,
      text_length: text.length,
    },
  };
});

