function sqlString(value) {
  if (value === null || value === undefined || value === '') {
    return 'NULL';
  }

  return `'${String(value).replace(/'/g, "''")}'`;
}

function sqlNumber(value) {
  if (value === null || value === undefined || value === '') {
    return 'NULL';
  }

  const n = Number(value);

  return Number.isFinite(n) ? String(n) : 'NULL';
}

function sqlTextArray(value) {
  if (!Array.isArray(value) || value.length === 0) {
    return 'NULL';
  }

  return `ARRAY[${value.map(v => sqlString(v)).join(', ')}]::text[]`;
}

return $input.all().map(item => {
  const p = item.json;

  const sql = `
INSERT INTO loan_products (
  provider,
  product_name,
  source_url,
  interest_rate_min,
  interest_rate_max,
  min_income,
  min_credit_score,
  max_credit_score,
  min_age,
  max_age,
  employment_required,
  eligibility_notes,
  is_active,
  last_seen_at
)
VALUES (
  ${sqlString(p.provider)},
  ${sqlString(p.product_name)},
  ${sqlString(p.source_url)},
  ${sqlNumber(p.interest_rate_min)},
  ${sqlNumber(p.interest_rate_max)},
  ${sqlNumber(p.min_income)},
  ${sqlNumber(p.min_credit_score)},
  ${sqlNumber(p.max_credit_score)},
  ${sqlNumber(p.min_age)},
  ${sqlNumber(p.max_age)},
  ${sqlTextArray(p.employment_required)},
  ${sqlString(p.eligibility_notes)},
  TRUE,
  NOW()
)
ON CONFLICT (provider, product_name)
DO UPDATE SET
  source_url = EXCLUDED.source_url,
  interest_rate_min = EXCLUDED.interest_rate_min,
  interest_rate_max = EXCLUDED.interest_rate_max,
  min_income = EXCLUDED.min_income,
  min_credit_score = EXCLUDED.min_credit_score,
  max_credit_score = EXCLUDED.max_credit_score,
  min_age = EXCLUDED.min_age,
  max_age = EXCLUDED.max_age,
  employment_required = EXCLUDED.employment_required,
  eligibility_notes = EXCLUDED.eligibility_notes,
  is_active = TRUE,
  last_seen_at = NOW();
`;

  return {
    json: {
      ...p,
      sql,
    },
  };
});

return $input.all().map((item, index) => {
  const sourceItems = $('Source List').all();

  return {
