const rawText =
  $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text ?? '';

if (!rawText) {
  throw new Error('Gemini returned empty response');
}

const cleaned = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`Gemini returned invalid JSON: ${error.message}`);
}

const products = Array.isArray(parsed)
  ? parsed
  : parsed.products;

if (!Array.isArray(products)) {
  throw new Error('Gemini response does not contain a products array');
}

const validProducts = products.filter(product => {
  return (
    product &&
    typeof product === 'object' &&
    product.product_name
  );
});

return validProducts.map(product => ({
  json: {
    provider: product.provider ?? null,
    source_url: product.source_url ?? null,

    product_name: product.product_name ?? null,
    interest_rate_min: product.interest_rate_min ?? null,
    interest_rate_max: product.interest_rate_max ?? null,
    min_income: product.min_income ?? null,
    min_credit_score: product.min_credit_score ?? null,
    max_credit_score: product.max_credit_score ?? null,
    min_age: product.min_age ?? null,
    max_age: product.max_age ?? null,

    employment_required: Array.isArray(product.employment_required)
      ? product.employment_required
      : null,

    eligibility_notes: product.eligibility_notes ?? null,
  },
}));
